import{_ as t,o as r,c as s,ak as n}from"./chunks/framework.B8jO0odJ.js";const g=JSON.parse('{"title":"A-Z lesson sources and assessment seeds","description":"Status: current source reference; lesson copy and questions are draft content.\\nThe lesson-collection GDD owns the ordered 39-lesson route, nine distinct minigames, lesson pane","frontmatter":{"title":"A-Z lesson sources and assessment seeds","description":"Status: current source reference; lesson copy and questions are draft content.\\nThe lesson-collection GDD owns the ordered 39-lesson route, nine distinct minigames, lesson pane","source":"docs/planning/a-z-complete-lesson-quiz-source-draft.md","category":"Learning content","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/planning/a-z-complete-lesson-quiz-source-draft.md","filePath":"content/docs/planning/a-z-complete-lesson-quiz-source-draft.md"}'),o={name:"content/docs/planning/a-z-complete-lesson-quiz-source-draft.md"};function a(i,e,d,c,l,h){return r(),s("div",null,[...e[0]||(e[0]=[n('<div><h1 id="a-z-lesson-sources-and-assessment-seeds">A-Z lesson sources and assessment seeds<a class="header-anchor" href="#a-z-lesson-sources-and-assessment-seeds" aria-label="Link to this section">​</a></h1><p><strong>Status: current source reference; lesson copy and questions are draft content.</strong> The <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">lesson-collection GDD</a> owns the ordered 39-lesson route, nine distinct minigames, lesson panels, and required review questions. The owner confirmed 13 required review questions per world, one per lesson, with errors retried until all are corrected. This page preserves source meanings and question seeds; it does not define a second gameplay route or prove implementation or learning effectiveness. Current authorization is documentation and preparation only; game development requires final owner approval.</p><h2 id="what-complete-means-here">What “complete” means here<a class="header-anchor" href="#what-complete-means-here" aria-label="Link to this section">​</a></h2><ul><li>The 26 original A-Z source headings and PDF locators remain in the two source tables below.</li><li>Thirteen added AI terms have their own primary references; they are not chapters from the Web3 book.</li><li>Every term has one stable lesson ID, meaning, and draft check with an answer and reason.</li><li>The tables retain source-letter order for lookup; play follows prerequisite order in the GDD.</li><li>Completeness describes inventory coverage only, not educator validation, original-text verification, or game readiness.</li></ul><p>The <a href="/Chainy-Docs/content/docs/archive/source-material/web3-young-learners-encyclopedia-a-z-contents.html">book contents inventory</a> records all 43 PDF pages. The original book calls its entire A-Z collection Web3; assigning 13 terms to Web3 and 13 to Blockchain is a teaching choice in this project. The <a href="/Chainy-Docs/content/docs/planning/ai-source-research.html">AI research note</a> explains the separate source selection. An AI term paired with a book letter is a different concept, not a synonym.</p><p><strong>Source limit:</strong> The repository contains the detailed contents inventory, not the original encyclopedia PDF. The book-term explanations below paraphrase the inventory&#39;s chapter summaries. Exact nuance, visuals, and permission to reuse source wording still need checking against the original PDF. This page is not a transcription of the 26 chapters.</p><h2 id="source-and-accuracy-rules">Source and accuracy rules<a class="header-anchor" href="#source-and-accuracy-rules" aria-label="Link to this section">​</a></h2><p>Use fictional records, messages, and examples. No lesson requires a real exchange, QR scan, wallet connection, secret, payment, or investment. Fixed prices or receipt fields in a sample question are explanatory diagrams, not player balances or an economy system. Jupiter and XRP remain named examples from the source inventory; their inclusion is not an endorsement, live service instruction, or verification of current product details.</p><p>A linked record can reveal a mismatch against a trusted reference under stated assumptions; it does not establish that the recorded event really occurred. A token or NFT record does not automatically establish copyright or financial value. A wallet interface manages access; the wallet picture is not physical storage for coins. A zero-knowledge illustration is not a cryptographic proof implementation. AI teaching simulations must stay visibly labeled as scripted; do not describe authored responses as a player-trained model or live generation.</p><p>Retained accuracy references: <a href="https://csrc.nist.gov/pubs/ir/8202/final">NIST IR 8202</a>, <a href="https://ethereum.org/wallets/">Ethereum wallets</a>, <a href="https://ethereum.org/developers/docs/smart-contracts/">Ethereum smart contracts</a>, <a href="https://developers.google.com/machine-learning/intro-to-ml/supervised">Google supervised learning</a>, and <a href="https://developers.google.com/machine-learning/crash-course/overfitting/dividing-datasets">Google evaluation data separation</a>. These references and the book&#39;s simplified analogies need checking during final content review; this documentation reconciliation does not assert a new source audit.</p><h2 id="recommended-lesson-order-and-gdd-fit">Recommended lesson order and GDD fit<a class="header-anchor" href="#recommended-lesson-order-and-gdd-fit" aria-label="Link to this section">​</a></h2><p>The confirmed journey is Web3, then Blockchain, then AI. Each world has 13 individual lessons in prerequisite order, including three distinct minigame lessons. Ordinary lessons are collected through island encounters; minigame lessons require their ordered prerequisites and successful activity. After all 13 entries are recorded, the player completes 13 required review questions, corrects every error, and unlocks the next world.</p><p>Use the <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html#7-complete-lesson-route">complete lesson route</a> for sequence and the <a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html#8-nine-distinct-minigames">minigame specifications</a> for mechanics. The IDs below map the source inventory to that route without duplicating it. The two-choice samples are editorial seeds; the GDD&#39;s four-choice review bank is the current gameplay payload. Collection, assisted correction, and first-response correctness are different observations.</p><h2 id="original-source-terms-web3-primary-world-1313">Original source terms: Web3 primary world (13/13)<a class="header-anchor" href="#original-source-terms-web3-primary-world-1313" aria-label="Link to this section">​</a></h2><p>The <code>PDF p.</code> locators below refer to the 43-page <em>Web3 Young Learners Encyclopedia</em>. The exact source headings are retained. The check shown after each heading is a <strong>draft sample item</strong>.</p><table><thead><tr><th>Lesson ID</th><th>Letter / source</th><th>Teaching point</th><th>Draft learner check, answer and feedback</th></tr></thead><tbody><tr><td>LC-W03</td><td><strong>A — Altcoins</strong> (PDF p. 8)</td><td>Coins other than Bitcoin can have different intended uses. A name alone says little about safety or value.</td><td>“Are all digital coins Bitcoin?” <strong>No.</strong> Other coins exist; investigate what a named coin is for.</td></tr><tr><td>LC-W02</td><td><strong>C — Cryptocurrency</strong> (p. 10)</td><td>A digital asset used for exchange on a cryptographic network; it is not the same as government-issued money.</td><td>“Is a fictional cryptocurrency shown on a lesson poster the learner&#39;s real cash?” <strong>No.</strong> The illustration teaches a concept without issuing a real financial asset.</td></tr><tr><td>LC-W08</td><td><strong>E — Exchanges (Know What, Not How)</strong> (p. 12)</td><td>An exchange is a service where people trade digital assets. Recognition is enough for this course.</td><td>“A website offers to swap one coin for another. Is it an exchange or a wallet backup?” <strong>Exchange.</strong> Trading and credential recovery are different tasks.</td></tr><tr><td>LC-W01</td><td><strong>F — Fiat Currency</strong> (p. 13)</td><td>Government-issued money, including cash and ordinary account balances.</td><td>“Which is fiat: pesos in a bank account or a cryptocurrency example?” <strong>Pesos.</strong> Digital display does not make ordinary money cryptocurrency.</td></tr><tr><td>LC-W11</td><td><strong>H — HODL</strong> (p. 15)</td><td>Slang for holding a cryptocurrency; it is not a reliable investment rule.</td><td>“A post says ‘HODL means a price must rise.’ Is that supported?” <strong>No.</strong> Slang predicts nothing about price.</td></tr><tr><td>LC-W06</td><td><strong>I — Identity and Online Safety</strong> (p. 16)</td><td>Protect private information; a public nickname does not justify revealing credentials.</td><td>“A stranger asks for a password to verify your account. Share it or refuse?” <strong>Refuse.</strong> Verification claims do not make a secret safe to share.</td></tr><tr><td>LC-W09</td><td><strong>J — Jupiter (JUP)</strong> (p. 17)</td><td>The book gives a named Solana swap service as an example, not a tool learners need to use.</td><td>“Is Jupiter in this chapter a required step for the player?” <strong>No.</strong> It is an informational example; the game has no live swap.</td></tr><tr><td>LC-W07</td><td><strong>Q — QR Codes in Web3</strong> (p. 24)</td><td>A QR code may lead to a site or app; its appearance does not verify the destination.</td><td>“A random poster&#39;s code promises a prize. Scan or check its source first?” <strong>Check first.</strong> Codes can hide an unsafe link. No real scanning is needed in play.</td></tr><tr><td>LC-W12</td><td><strong>R — Risks, Red Flags &amp; Staying Scam-Safe</strong> (p. 25)</td><td>Urgency, impossible rewards, suspicious links and requests for secrets are warning signs.</td><td>“A message demands a secret to claim free coins in one minute. Trust or reject?” <strong>Reject.</strong> The deadline and secret request are red flags.</td></tr><tr><td>LC-W13</td><td><strong>U — Understanding Web3 Safety</strong> (p. 28)</td><td>Pause, verify independently and seek trusted help before acting.</td><td>“You cannot verify a new wallet link. Proceed or ask a trusted adult/guide?” <strong>Ask.</strong> Uncertainty is a reason to pause.</td></tr><tr><td>LC-W10</td><td><strong>V — Volatility (What It Means)</strong> (p. 29)</td><td>The price of an asset may change rapidly; future value is uncertain.</td><td>“A coin rose yesterday. Is tomorrow&#39;s price guaranteed?” <strong>No.</strong> Past movement does not guarantee a new price.</td></tr><tr><td>LC-W05</td><td><strong>W — Wallets (Read-Only Awareness)</strong> (p. 30)</td><td>A wallet helps a user manage access and transactions; secret recovery information must stay private.</td><td>“Does a wallet screen mean coins are physically stored in the phone?” <strong>No.</strong> The interface helps access a network account; no real wallet is used.</td></tr><tr><td>LC-W04</td><td><strong>X — XRP</strong> (p. 31)</td><td>A named cryptocurrency example; recognition does not imply endorsement or a lesson in buying it.</td><td>“Is XRP a type of government-issued fiat currency?” <strong>No.</strong> It is a named cryptocurrency example in the book.</td></tr></tbody></table><h2 id="original-source-terms-blockchain-primary-world-1313">Original source terms: Blockchain primary world (13/13)<a class="header-anchor" href="#original-source-terms-blockchain-primary-world-1313" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Lesson ID</th><th>Letter / source</th><th>Teaching point</th><th>Draft learner check, answer and feedback</th></tr></thead><tbody><tr><td>LC-B02</td><td><strong>B — Blockchain</strong> (PDF p. 9)</td><td>A chain organizes records into linked blocks shared under network rules; tampering can be detected under stated assumptions.</td><td>“The local copy shows price 6, but trusted receipt shows 8. Which needs investigation?” <strong>The local copy.</strong> A disagreement signals checking, not automatic proof of what happened.</td></tr><tr><td>LC-B03</td><td><strong>D — Decentralization</strong> (p. 11)</td><td>Control or recordkeeping is distributed among participants rather than one operator.</td><td>“Are three screenshots on one phone three independent participants?” <strong>No.</strong> Copies on one device do not create distributed control.</td></tr><tr><td>LC-B06</td><td><strong>G — Gas Fees</strong> (p. 14)</td><td>Some blockchain actions require a network-use fee separate from an item&#39;s price; fees vary by network and load.</td><td>“A fixed diagram shows item price 8, fee 1. Is the fee part of the item&#39;s listed price?” <strong>No.</strong> It is a separate transaction cost.</td></tr><tr><td>LC-B04</td><td><strong>K — Keys (Public &amp; Private)</strong> (p. 18)</td><td>Public receiving information may be shared; private signing/access information must be protected.</td><td>“Which may be shared in the fictional example: receiving address or private key?” <strong>Receiving address.</strong> The private key controls access.</td></tr><tr><td>LC-B01</td><td><strong>L — Ledger</strong> (p. 19)</td><td>A ledger records transactions; compare a record with an accepted reference before deciding which copy to use.</td><td>“The reference says 8; a display says 6. Accept 6 without checking?” <strong>No.</strong> Inspect the discrepancy first.</td></tr><tr><td>LC-B10</td><td><strong>M — Mining &amp; Validators</strong> (p. 20)</td><td>Different networks use different participants and methods to propose/check blocks; miners and validators are not universal interchangeable roles.</td><td>“Must every blockchain have both miners and validators doing the same job?” <strong>No.</strong> The network&#39;s design determines roles.</td></tr><tr><td>LC-B08</td><td><strong>N — NFTs (Non-Fungible Tokens)</strong> (p. 21)</td><td>A unique token record can indicate ownership of a specific token; that alone does not establish value, copyright or ownership of an underlying file.</td><td>“Item #014 has a unique token record. Does that guarantee resale value?” <strong>No.</strong> Uniqueness and market value differ.</td></tr><tr><td>LC-B05</td><td><strong>O — On-Chain vs Off-Chain</strong> (p. 22; printed locator <code>0/15</code>)</td><td>An on-chain action changes the shared ledger; an off-chain action occurs elsewhere.</td><td>“A private note in the game journal appears only on this phone. Is it on-chain?” <strong>No.</strong> A local note is not a shared blockchain record.</td></tr><tr><td>LC-B11</td><td><strong>P — Proof Systems</strong> (p. 23)</td><td>Proof of Work and Proof of Stake are different ways networks select/check block additions; neither is a classroom vote.</td><td>“Does the player&#39;s tap alone establish network consensus?” <strong>No.</strong> The card activity represents rules; it is not a live network.</td></tr><tr><td>LC-B09</td><td><strong>S — Smart Contracts</strong> (p. 26)</td><td>A deployed program follows coded conditions when given relevant inputs; a classroom if/then example is an analogy.</td><td>“A programmed rule opens a gate after a valid permit is supplied. Without that input, should it open?” <strong>No.</strong> The stated condition has not been met.</td></tr><tr><td>LC-B07</td><td><strong>T — Tokens (Not Toys!)</strong> (p. 27)</td><td>A token can represent a digital unit, access right or item; it is not automatically real-world money.</td><td>“Does every game token have cash value?” <strong>No.</strong> Its purpose and rights depend on the system.</td></tr><tr><td>LC-B12</td><td><strong>Y — Your Data and Privacy in Web3</strong> (p. 32)</td><td>Public records and addresses can expose activity; pseudonyms are not a promise of anonymity.</td><td>“A public address has no printed name. Is its activity necessarily private?” <strong>No.</strong> Public activity may still be observed or linked.</td></tr><tr><td>LC-B13</td><td><strong>Z — Zero-Knowledge Proofs</strong> (p. 33)</td><td>Some protocols can prove a claim without exposing the underlying detail; the age example is conceptual.</td><td>“Could a proof show ‘old enough’ without showing the exact birthday?” <strong>Yes, in a suitable system.</strong> The game illustrates the idea; it does not implement a cryptographic proof.</td></tr></tbody></table><p><strong>Book support outside A–Z:</strong> The glossary on PDF p. 35 defines block, node, consensus, seed phrase and related terms. The scam and digital citizenship guidance on pp. 36–38 supports safety feedback. Opening remarks on pp. 2–7 and closing/credits on pp. 39–43 provide purpose and attribution, not more letter lessons. The source explicitly frames exchanges and wallets as awareness topics and does not teach trading or investing.</p><h2 id="added-ai-terms-13-paired-letter-slots">Added AI terms: 13 paired letter slots<a class="header-anchor" href="#added-ai-terms-13-paired-letter-slots" aria-label="Link to this section">​</a></h2><p>These terms are <strong>not from the Web3 encyclopedia</strong>. They were selected at a fundamental level using the primary references linked in each row. The original term in the same letter remains in its Web3 or Blockchain world. The check is draft game copy; the link supports the term and accuracy, not the invented fictional example.</p><table><thead><tr><th>Lesson ID</th><th>Paired letter / AI term</th><th>Teaching point and source</th><th>Draft learner check, answer and feedback</th></tr></thead><tbody><tr><td>LC-A01</td><td><strong>A — Artificial intelligence</strong></td><td>A task-focused system can infer predictions, recommendations, decisions or content from inputs. <a href="https://oecd.ai/en/wonk/definition">OECD AI system definition</a></td><td>“Which example uses learned patterns for an unfamiliar request: a fixed greeting screen or a trained classifier?” <strong>The trained classifier.</strong> The greeting screen alone does not demonstrate learned prediction.</td></tr><tr><td>LC-A10</td><td><strong>B — Bias</strong></td><td>Missing or skewed examples can produce systematically uneven outcomes. <a href="https://developers.google.com/machine-learning/crash-course/fairness/types-of-bias">Google: types of bias</a></td><td>“All training cards show daytime requests; the bot often misreads night requests. What should be checked?” <strong>Missing night examples.</strong> More of the same daytime cards may not fix the gap.</td></tr><tr><td>LC-A07</td><td><strong>C — Classification</strong></td><td>A classifier predicts one category from input features. <a href="https://developers.google.com/machine-learning/intro-to-ml/what-is-ml">Google: what is ML?</a></td><td>“The bot marks a request Routine or Review. Is that classification or image generation?” <strong>Classification.</strong> It chooses between defined categories.</td></tr><tr><td>LC-A02</td><td><strong>D — Dataset</strong></td><td>A dataset is a collection of examples; coverage and quality matter. <a href="https://developers.google.com/machine-learning/crash-course/overfitting/data-characteristics">Google: data characteristics</a></td><td>“Are three copies of one request as useful as three different relevant cases?” <strong>No.</strong> Copies do not increase the range of cases.</td></tr><tr><td>LC-A03</td><td><strong>F — Feature</strong></td><td>A feature is an input detail used for a prediction. <a href="https://developers.google.com/machine-learning/intro-to-ml/supervised">Google: supervised learning</a></td><td>“To review a delivery request, which field matters more: destination mismatch or card color?” <strong>Destination mismatch.</strong> It bears on the decision; color does not in this example.</td></tr><tr><td>LC-A12</td><td><strong>G — Generative AI</strong></td><td>Generative models can create new text, images or other content; generated answers need verification. <a href="https://developers.google.com/machine-learning/glossary/generative">Google: generative glossary</a></td><td>“An authored ‘AI answer’ says fee 2, while the receipt says fee 1. Trust the answer or the receipt?” <strong>Receipt.</strong> Plausible text can conflict with evidence. Label the game example as scripted.</td></tr><tr><td>LC-A11</td><td><strong>H — Human oversight</strong></td><td>People should retain agency and check consequential AI suggestions. <a href="https://www.unesco.org/en/articles/ai-competency-framework-students">UNESCO student framework</a></td><td>“The helper suggests dispatch despite a missing address. Auto-send or pause for a person to check?” <strong>Pause.</strong> Missing evidence needs human judgment.</td></tr><tr><td>LC-A04</td><td><strong>L — Label</strong></td><td>A label is the known target answer attached to a training example. <a href="https://developers.google.com/machine-learning/intro-to-ml/supervised">Google: supervised learning</a></td><td>“A past request is marked Review. Is ‘Review’ its label or its destination?” <strong>Label.</strong> It is the known category supplied with the example.</td></tr><tr><td>LC-A06</td><td><strong>M — Model</strong></td><td>A trained model uses learned patterns to infer an output for a new input. <a href="https://developers.google.com/machine-learning/glossary/fundamentals">Google: ML glossary</a></td><td>“If the bot repeats a fixed list of authored replies regardless of examples, has the player trained a model?” <strong>No.</strong> Fixed authored replies do not demonstrate a model fitting from examples.</td></tr><tr><td>LC-A08</td><td><strong>P — Prediction</strong></td><td>A prediction is a model&#39;s proposed output, which can be wrong. <a href="https://developers.google.com/machine-learning/intro-to-ml/supervised">Google: supervised learning</a></td><td>“The bot predicts Routine, but the verified case is Review. Which is ground truth here?” <strong>The verified case.</strong> A prediction is a claim to check.</td></tr><tr><td>LC-A13</td><td><strong>R — Responsible AI</strong></td><td>Consider intended use, privacy, possible harm, fairness and human control. <a href="https://www.unesco.org/en/articles/ai-competency-framework-students">UNESCO student framework</a>; <a href="https://airc.nist.gov/airmf-resources/airmf/3-sec-characteristics/">NIST AI RMF characteristics</a></td><td>“Should real learner identities be placed in a practice dataset when fictional examples suffice?” <strong>No.</strong> Use the minimum data needed for the learning activity.</td></tr><tr><td>LC-A05</td><td><strong>T — Training</strong></td><td>A model changes or fits from examples during training; showing a scripted answer is different. <a href="https://developers.google.com/machine-learning/intro-to-ml/supervised">Google: supervised learning</a></td><td>“After correcting a training label, the model&#39;s later output changes. What likely influenced it?” <strong>The corrected example.</strong> Verify with a fresh case; one change is not broad reliability.</td></tr><tr><td>LC-A09</td><td><strong>V — Validation</strong></td><td>Check a model on examples separate from training; keep final test cases untouched. <a href="https://developers.google.com/machine-learning/crash-course/overfitting/dividing-datasets">Google: dividing datasets</a></td><td>“The bot gets every memorized training card right. Is that enough to claim it works on new cards?” <strong>No.</strong> Try unseen cases and inspect errors.</td></tr></tbody></table><p><strong>AI activity boundary:</strong> All three current AI minigames are explicitly labeled offline teaching simulations. They illustrate labeling, checking unfamiliar cases, and verifying generated-content examples with authored behavior. The player does not train a model, invoke a live generator, or authorize an autonomous agent. The Training and Model lessons explain the real concepts without claiming that the app performs them. Actual model fitting is outside current scope, not a promised later feature. See <a href="https://ai4k12.org/gradeband-progression-charts/">AI4K12 grade-band progression</a> and <a href="https://www.unesco.org/en/articles/ai-competency-framework-students">UNESCO&#39;s AI Competency Framework for Students</a> for age-level and human agency review.</p><h2 id="direct-comparison-with-the-simplified-gdd">Direct comparison with the simplified GDD<a class="header-anchor" href="#direct-comparison-with-the-simplified-gdd" aria-label="Link to this section">​</a></h2><p>The earlier 15-cluster route, three-game recommendation, shared-purchase dependency, optional AI classifier, and smaller review samples are superseded. Read the <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/planning/a-z-complete-lesson-quiz-source-draft.html#direct-comparison-with-the-simplified-gdd">archived source-pack proposal</a> for that comparison. The current GDD owns scope and rules; old proposals do not create future delivery promises.</p><h2 id="editorial-completion-checklist">Editorial completion checklist<a class="header-anchor" href="#editorial-completion-checklist" aria-label="Link to this section">​</a></h2><p>For each lesson, check the objective, exact panel copy, visible fictional evidence, plausible alternatives, correct answer, explanatory feedback, source locator, and stable content/version ID. Check that the required review item tests the concept actually introduced by that lesson. Do not copy the sample answer pattern into the final review or claim that a repeated correct answer proves independent understanding. Record first-response correctness separately from supported correction and from abandoned reviews.</p><p>Content review should verify security and AI accuracy, reading load for ages 12-17, and whether a learner can explain the reasoning in a fresh example. Educator review and learner testing remain pending; no curriculum approval, validated instrument, or learning gain is asserted. The <a href="/Chainy-Docs/content/docs/learning-foundations.html">learning foundations</a> explains this distinction. Preserve integration, device QA, manuscript evidence, and rehearsal time before the November 21, 2026 pre-final.</p></div>',1)])])}const m=t(o,[["render",a]]);export{g as __pageData,m as default};
